package cmd

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

var updateCLIRef = flag.Bool("update", false, "rewrite docs/reference/cli.md")

const cliRefPath = "../../../docs/reference/cli.md"

// The comment sits below the H1: mkdocs takes the page title from a first-line H1 only.
const cliRefHeader = "# ach-cli command reference\n\n" +
	"<!-- Generated by make gen-cli-ref-docs. Do not edit. -->\n\n" +
	"Every `ach-cli` command, as printed by `--help`.\n\n"

// renderCLIRef writes the help text of c and of every available subcommand.
// InitDefaultHelpFlag adds what cobra adds on Execute, so the output does not
// depend on whether another test executed the command first.
func renderCLIRef(b *bytes.Buffer, c *cobra.Command, depth int) {
	if depth > 0 && !c.IsAvailableCommand() {
		return
	}
	c.InitDefaultHelpFlag()
	heading := "##"
	if depth > 1 {
		heading = "###"
	}
	desc := c.Long
	if desc == "" {
		desc = c.Short
	}
	fmt.Fprintf(b, "%s %s\n\n```text\n%s\n\n%s```\n\n",
		heading, c.CommandPath(), strings.TrimSpace(desc), c.UsageString())
	for _, sub := range c.Commands() {
		renderCLIRef(b, sub, depth+1)
	}
}

// TestCLIReference fails when docs/reference/cli.md differs from the command
// tree; -update rewrites the page.
func TestCLIReference(t *testing.T) {
	rootCmd.InitDefaultHelpCmd()
	rootCmd.InitDefaultCompletionCmd()
	rootCmd.InitDefaultVersionFlag()
	var b bytes.Buffer
	b.WriteString(cliRefHeader)
	renderCLIRef(&b, rootCmd, 0)

	if *updateCLIRef {
		if err := os.WriteFile(cliRefPath, b.Bytes(), 0o600); err != nil {
			t.Fatal(err)
		}
		return
	}
	want, err := os.ReadFile(cliRefPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(want, b.Bytes()) {
		t.Fatal("docs/reference/cli.md is stale: run `./scripts/dev.sh make gen-cli-ref-docs`")
	}
}
